import{_ as s,I as o,o as d,c as n,b6 as a,J as t}from"./chunks/framework.BUXTSoD9.js";const f=JSON.parse('{"title":"Visualización de Datos y Dashboards","description":"","frontmatter":{},"headers":[],"relativePath":"es-es/appendix/5-data/data-visualization.md","filePath":"es-es/appendix/5-data/data-visualization.md"}'),l={name:"es-es/appendix/5-data/data-visualization.md"};function c(p,e,u,m,g,h){const i=o("ChartTypeSelectorDemo"),r=o("DashboardLayoutDemo");return d(),n("div",null,[e[0]||(e[0]=a('<h1 id="visualizacion-de-datos-y-dashboards" tabindex="-1">Visualización de Datos y Dashboards <a class="header-anchor" href="#visualizacion-de-datos-y-dashboards" aria-label="Permalink to “Visualización de Datos y Dashboards”">​</a></h1><div class="tip custom-block"><p class="custom-block-title">Prefacio</p><p><strong>Una buena tabla vale más que mil filas de datos.</strong> La visualización de datos transforma números abstractos en expresiones visuales intuitivas, permitiendo a las personas comprender la historia detrás de los datos en cuestión de segundos. Desde los gráficos de Excel hasta los paneles de monitorización de Grafana, la visualización está en todas partes.</p></div><p><strong>¿Qué aprenderás en este artículo?</strong></p><p>Después de completar este capítulo, obtendrás:</p><ul><li><strong>Selección de gráficos</strong>: Elegir el tipo de gráfico más adecuado según el propósito de los datos</li><li><strong>Principios de visualización</strong>: Dominar los principios de diseño fundamentales de la visualización de datos</li><li><strong>Diseño de dashboards</strong>: Conocer los patrones de diseño de diferentes tipos de dashboards</li><li><strong>Ecosistema de herramientas</strong>: Familiarizarte con el posicionamiento y la selección de las herramientas de visualización más populares</li><li><strong>Errores comunes</strong>: Evitar gráficos engañosos y errores frecuentes de visualización</li></ul><table tabindex="0"><thead><tr><th>Capítulo</th><th>Contenido</th><th>Conceptos clave</th></tr></thead><tbody><tr><td><strong>Capítulo 1</strong></td><td>Selección de tipos de gráficos</td><td>Comparación, tendencia, proporción, distribución, relación</td></tr><tr><td><strong>Capítulo 2</strong></td><td>Principios de diseño de visualización</td><td>Ratio tinta-datos, consistencia, legibilidad</td></tr><tr><td><strong>Capítulo 3</strong></td><td>Diseño de dashboards</td><td>Panorámico, comparativo, de profundización, en tiempo real</td></tr><tr><td><strong>Capítulo 4</strong></td><td>Selección de herramientas</td><td>ECharts, D3, Grafana, Metabase</td></tr><tr><td><strong>Capítulo 5</strong></td><td>Errores comunes</td><td>Ejes truncados, gráficos de pastel 3D, uso excesivo de color</td></tr></tbody></table><hr><h2 id="_0-panorama-general-¿por-que-necesitamos-visualizacion" tabindex="-1">0. Panorama general: ¿Por qué necesitamos visualización? <a class="header-anchor" href="#_0-panorama-general-¿por-que-necesitamos-visualizacion" aria-label="Permalink to “0. Panorama general: ¿Por qué necesitamos visualización?”">​</a></h2><p>El cerebro humano procesa información visual mucho más rápido que el texto. Un gráfico de líneas te permite ver rápidamente que &quot;las ventas del mes pasado están disminuyendo&quot;, mientras que la misma información presentada en una tabla requeriría comparar fila por fila para llegar a la misma conclusión.</p><p>El valor fundamental de la visualización:</p><ul><li><strong>Descubrir patrones</strong>: Tendencias, ciclos y valores atípicos son evidentes de un vistazo en un gráfico</li><li><strong>Apoyar la toma de decisiones</strong>: Permite que incluso el personal no técnico comprenda los datos y participe en las decisiones</li><li><strong>Eficiencia de comunicación</strong>: Una imagen vale más que mil palabras, reduciendo la ambigüedad en la interpretación de datos</li></ul><div class="tip custom-block"><p class="custom-block-title">Visualización ≠ Bonito</p><p>El objetivo de la visualización es <strong>transmitir información</strong>, no lucirse. Un gráfico de barras sencillo pero preciso es mucho más valioso que un gráfico 3D llamativo pero difícil de entender.</p></div><hr><h2 id="_1-seleccion-de-tipos-de-graficos-usa-el-grafico-correcto-para-contar-la-historia-correcta" tabindex="-1">1. Selección de tipos de gráficos: Usa el gráfico correcto para contar la historia correcta <a class="header-anchor" href="#_1-seleccion-de-tipos-de-graficos-usa-el-grafico-correcto-para-contar-la-historia-correcta" aria-label="Permalink to “1. Selección de tipos de gráficos: Usa el gráfico correcto para contar la historia correcta”">​</a></h2><p>El primer paso para elegir un gráfico no es &quot;qué gráfico me gusta&quot;, sino &quot;qué información quiero transmitir&quot;. Diferentes propósitos de datos corresponden a diferentes tipos de gráficos óptimos.</p>',15)),t(i),e[1]||(e[1]=a('<h3 id="tabla-de-referencia-rapida-para-seleccion-de-graficos" tabindex="-1">Tabla de referencia rápida para selección de gráficos <a class="header-anchor" href="#tabla-de-referencia-rapida-para-seleccion-de-graficos" aria-label="Permalink to “Tabla de referencia rápida para selección de gráficos”">​</a></h3><table tabindex="0"><thead><tr><th>Propósito de datos</th><th>Gráfico recomendado</th><th>No recomendado</th><th>Razón</th></tr></thead><tbody><tr><td>Comparar magnitudes</td><td>Gráfico de barras, gráfico de barras horizontales</td><td>Gráfico de pastel</td><td>El ojo humano es más sensible a las diferencias de longitud que a las de ángulo</td></tr><tr><td>Mostrar tendencias</td><td>Gráfico de líneas, gráfico de áreas</td><td>Gráfico de barras</td><td>La continuidad de la línea implica la continuidad del tiempo</td></tr><tr><td>Mostrar proporciones</td><td>Gráfico de pastel (≤5 categorías), gráfico de barras apiladas</td><td>Gráfico de pastel 3D</td><td>La perspectiva 3D distorsiona las proporciones de área</td></tr><tr><td>Mostrar distribución</td><td>Histograma, diagrama de caja</td><td>Gráfico de líneas</td><td>La distribución requiere ver frecuencias, no tendencias</td></tr><tr><td>Mostrar relaciones</td><td>Gráfico de dispersión, gráfico de burbujas</td><td>Gráfico de barras</td><td>La relación entre dos variables continuas requiere un espacio bidimensional</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Una regla de decisión simple</p><ul><li><strong>Una variable</strong> → Histograma (distribución) o tarjeta numérica (KPI)</li><li><strong>Dos variables</strong> → Gráfico de líneas (tiempo vs. valor) o gráfico de dispersión (valor vs. valor)</li><li><strong>Múltiples categorías</strong> → Gráfico de barras (comparación) o gráfico de pastel (proporción, ≤5 categorías)</li><li><strong>Multidimensional</strong> → Gráfico de radar o gráfico de coordenadas paralelas</li></ul></div><hr><h2 id="_2-principios-de-diseno-de-visualizacion-deja-que-los-datos-hablen" tabindex="-1">2. Principios de diseño de visualización: Deja que los datos hablen <a class="header-anchor" href="#_2-principios-de-diseno-de-visualizacion-deja-que-los-datos-hablen" aria-label="Permalink to “2. Principios de diseño de visualización: Deja que los datos hablen”">​</a></h2><p>Una buena visualización no es &quot;bonita&quot;, sino &quot;comprensible&quot;. Varios principios clásicos propuestos por Edward Tufte en &quot;The Visual Display of Quantitative Information&quot; siguen siendo una referencia importante para el diseño de visualización hoy en día.</p><table tabindex="0"><thead><tr><th>Principio</th><th>Descripción</th><th>Contraejemplo</th></tr></thead><tbody><tr><td>Ratio tinta-datos</td><td>La proporción de &quot;tinta&quot; utilizada para mostrar datos en el gráfico debe ser lo más alta posible</td><td>Exceso de líneas de cuadrícula, elementos decorativos</td></tr><tr><td>Minimizar elementos no informativos</td><td>Eliminar elementos visuales que no transmitan información</td><td>Efectos 3D, sombras, fondos degradados</td></tr><tr><td>Escala consistente</td><td>Los ejes comienzan desde cero, con intervalos uniformes; si se trunca un eje, debe indicarse claramente</td><td>Eje Y comienza en 95 sin indicarlo</td></tr><tr><td>Uso razonable del color</td><td>Usar color para codificar información, no para decorar</td><td>Colores del arcoíris para datos ordenados</td></tr><tr><td>Etiquetado claro</td><td>Título, etiquetas de ejes, leyenda y unidades son indispensables</td><td>Sin unidades, sin rango de tiempo</td></tr></tbody></table><h3 id="_2-1-ratio-tinta-datos-data-ink-ratio" tabindex="-1">2.1 Ratio tinta-datos (Data-Ink Ratio) <a class="header-anchor" href="#_2-1-ratio-tinta-datos-data-ink-ratio" aria-label="Permalink to “2.1 Ratio tinta-datos (Data-Ink Ratio)”">​</a></h3><blockquote><p>La proporción de &quot;tinta&quot; utilizada para expresar datos en un gráfico respecto a la &quot;tinta&quot; total debe ser lo más alta posible.</p></blockquote><p>En pocas palabras: <strong>elimina todo elemento que no transmita información</strong>.</p><table tabindex="0"><thead><tr><th>Debería eliminarse</th><th>Debería conservarse</th></tr></thead><tbody><tr><td>Efectos 3D, sombras, degradados</td><td>Puntos de datos, etiquetas de ejes</td></tr><tr><td>Líneas de cuadrícula innecesarias</td><td>Líneas de referencia clave (como valores objetivo)</td></tr><tr><td>Iconos decorativos</td><td>Leyenda (cuando hay múltiples series)</td></tr><tr><td>Colores de fondo llamativos</td><td>Títulos y unidades claros</td></tr></tbody></table><h3 id="_2-2-principio-de-consistencia" tabindex="-1">2.2 Principio de consistencia <a class="header-anchor" href="#_2-2-principio-de-consistencia" aria-label="Permalink to “2.2 Principio de consistencia”">​</a></h3><ul><li><strong>Color consistente</strong>: La misma dimensión usa el mismo color en diferentes gráficos, por ejemplo, &quot;ingresos&quot; siempre en azul</li><li><strong>Escala consistente</strong>: Los ejes deben comenzar desde 0 siempre que sea posible, a menos que haya una razón justificada y se indique claramente</li><li><strong>Tiempo consistente</strong>: Los intervalos del eje temporal deben ser uniformes; no representes puntos temporales desiguales como si fueran equidistantes</li></ul><h3 id="_2-3-principio-de-legibilidad" tabindex="-1">2.3 Principio de legibilidad <a class="header-anchor" href="#_2-3-principio-de-legibilidad" aria-label="Permalink to “2.3 Principio de legibilidad”">​</a></h3><ul><li><strong>El título debe expresar una conclusión</strong>: No &quot;ventas mensuales&quot;, sino &quot;las ventas han disminuido durante 3 meses consecutivos&quot;</li><li><strong>Marcar puntos clave</strong>: Añade anotaciones en valores atípicos y puntos de inflexión para guiar la atención del lector</li><li><strong>Controlar la densidad de información</strong>: Un gráfico debe transmitir 1-2 mensajes centrales, no saturas demasiado</li></ul><div class="tip custom-block"><p class="custom-block-title">Tres reglas para el uso del color</p><ol><li><strong>Mismo indicador, mismo color</strong>: Los ingresos deben ser azules en todos los gráficos, no alternar entre azul y verde</li><li><strong>Datos ordenados con gradiente</strong>: La temperatura de baja a alta debe usar un gradiente de azul→rojo, no colores discretos</li><li><strong>Considerar la accesibilidad para daltónicos</strong>: Aproximadamente el 8% de los hombres tienen daltonismo rojo-verde; evita usar solo rojo y verde para distinguir información clave</li></ol></div><hr><h2 id="_3-diseno-de-dashboards-diferentes-escenarios-diferentes-patrones" tabindex="-1">3. Diseño de dashboards: Diferentes escenarios, diferentes patrones <a class="header-anchor" href="#_3-diseno-de-dashboards-diferentes-escenarios-diferentes-patrones" aria-label="Permalink to “3. Diseño de dashboards: Diferentes escenarios, diferentes patrones”">​</a></h2><p>Un dashboard es una combinación orgánica de múltiples gráficos. Un buen dashboard no es simplemente apilar gráficos juntos, sino seleccionar el patrón de diseño adecuado según el escenario de uso.</p>',19)),t(r),e[2]||(e[2]=a('<h3 id="cuatro-patrones-de-diseno-comunes" tabindex="-1">Cuatro patrones de diseño comunes <a class="header-anchor" href="#cuatro-patrones-de-diseno-comunes" aria-label="Permalink to “Cuatro patrones de diseño comunes”">​</a></h3><table tabindex="0"><thead><tr><th>Patrón de diseño</th><th>Estructura central</th><th>Escenario de uso</th><th>Puntos de diseño</th></tr></thead><tbody><tr><td>Panorámico global</td><td>Tarjetas KPI + gráfico de tendencias + tabla de detalles</td><td>Informes diarios para directivos, panel de operaciones</td><td>Los indicadores clave van en la parte superior, para ver los números críticos de un vistazo</td></tr><tr><td>Análisis comparativo</td><td>Diseño simétrico izquierdo-derecho</td><td>Tests A/B, análisis interanual/intermensual</td><td>Mantener las dimensiones de comparación consistentes, resaltar las diferencias</td></tr><tr><td>Análisis de profundización</td><td>Despliegue progresivo de resumen a detalle</td><td>Análisis de ventas, análisis de comportamiento de usuarios</td><td>Soportar interacción con clics, profundizar nivel por nivel</td></tr><tr><td>Monitorización en tiempo real</td><td>Números grandes + curvas en tiempo real + estado de alertas</td><td>Pantallas de eventos masivos, monitorización de servidores</td><td>Actualización automática, fondo oscuro, adecuado para proyección</td></tr></tbody></table><h3 id="_5-principios-del-diseno-de-dashboards" tabindex="-1">5 principios del diseño de dashboards <a class="header-anchor" href="#_5-principios-del-diseno-de-dashboards" aria-label="Permalink to “5 principios del diseño de dashboards”">​</a></h3><ol><li><strong>Primero pregunta &quot;quién lo va a ver&quot;</strong>: El CEO mira indicadores estratégicos, operaciones mira indicadores de proceso, los ingenieros miran indicadores técnicos</li><li><strong>Regla de los 5 segundos</strong>: El usuario debería comprender la información central del dashboard en 5 segundos</li><li><strong>Jerarquía de información</strong>: Lo más importante en la esquina superior izquierda, lo secundario debajo</li><li><strong>Minimizar el desplazamiento</strong>: Mostrar el contenido central en una pantalla, evitando que el usuario deba desplazarse para ver datos clave</li><li><strong>Espacio en blanco</strong>: No rellenes cada centímetro de espacio; el espacio en blanco adecuado hace la experiencia visual más cómoda</li></ol><div class="tip custom-block"><p class="custom-block-title">Dashboard vs. Informe</p><ul><li><strong>Dashboard</strong>: En tiempo real o cuasi-real, interactivo, orientado a la monitorización y la toma rápida de decisiones</li><li><strong>Informe</strong>: Generado periódicamente (diario/semanal/mensual), estático, orientado al análisis detallado y archivo</li></ul><p>No son mutuamente excluyentes, sino complementarios. El dashboard detecta problemas, el informe los analiza en profundidad.</p></div><hr><h2 id="_4-seleccion-de-herramientas-desde-bibliotecas-de-codigo-hasta-plataformas-bi" tabindex="-1">4. Selección de herramientas: Desde bibliotecas de código hasta plataformas BI <a class="header-anchor" href="#_4-seleccion-de-herramientas-desde-bibliotecas-de-codigo-hasta-plataformas-bi" aria-label="Permalink to “4. Selección de herramientas: Desde bibliotecas de código hasta plataformas BI”">​</a></h2><p>Las herramientas de visualización se pueden dividir en tres niveles: bibliotecas de gráficos a nivel de código, bibliotecas de gráficos para análisis de datos y plataformas BI. La elección depende de la complejidad de los requisitos, las necesidades de interacción y la capacidad técnica del equipo.</p><h3 id="_4-1-bibliotecas-de-graficos-a-nivel-de-codigo" tabindex="-1">4.1 Bibliotecas de gráficos a nivel de código <a class="header-anchor" href="#_4-1-bibliotecas-de-graficos-a-nivel-de-codigo" aria-label="Permalink to “4.1 Bibliotecas de gráficos a nivel de código”">​</a></h3><table tabindex="0"><thead><tr><th>Herramienta</th><th>Lenguaje/Plataforma</th><th>Características</th><th>Escenario de uso</th></tr></thead><tbody><tr><td>ECharts</td><td>JavaScript</td><td>Listo para usar, gran variedad de gráficos, documentación en chino completa</td><td>Gráficos integrados en sistemas empresariales</td></tr><tr><td>D3.js</td><td>JavaScript</td><td>Flexibilidad de bajo nivel, permite personalizar cualquier efecto de visualización</td><td>Visualización de datos altamente personalizada</td></tr><tr><td>Chart.js</td><td>JavaScript</td><td>Ligero y sencillo, fácil de aprender</td><td>Necesidades de gráficos simples</td></tr><tr><td>Matplotlib</td><td>Python</td><td>Biblioteca estándar de computación científica, gráficos estáticos</td><td>Análisis de datos, gráficos para publicaciones</td></tr><tr><td>Plotly</td><td>Python/JS</td><td>Gráficos interactivos, soporte 3D</td><td>Exploración de datos, Jupyter Notebook</td></tr></tbody></table><h3 id="_4-2-plataformas-bi-sin-codigo-bajo-codigo" tabindex="-1">4.2 Plataformas BI (sin código/bajo código) <a class="header-anchor" href="#_4-2-plataformas-bi-sin-codigo-bajo-codigo" aria-label="Permalink to “4.2 Plataformas BI (sin código/bajo código)”">​</a></h3><table tabindex="0"><thead><tr><th>Herramienta</th><th>Posicionamiento</th><th>Ventaja principal</th><th>Equipo adecuado</th></tr></thead><tbody><tr><td>Grafana</td><td>Visualización de monitorización</td><td>Buen soporte para datos de series temporales, integración de alertas</td><td>Equipos de operaciones/SRE</td></tr><tr><td>Metabase</td><td>BI ligero</td><td>Código abierto y gratuito, genera gráficos con SQL</td><td>Equipos pequeños y medianos para implementación rápida</td></tr><tr><td>Apache Superset</td><td>BI empresarial</td><td>Código abierto, soporta grandes fuentes de datos</td><td>Empresas con equipo de datos</td></tr><tr><td>Tableau</td><td>BI comercial</td><td>Operación de arrastrar y soltar, excelentes resultados visuales</td><td>Analistas de negocio</td></tr><tr><td>Power BI</td><td>BI comercial</td><td>Buena integración con el ecosistema Microsoft</td><td>Empresas que usan el stack tecnológico de Microsoft</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Recomendaciones de selección</p><ul><li><strong>Desarrolladores integrando gráficos en productos</strong> → ECharts (buen ecosistema en chino) o Chart.js (escenarios simples)</li><li><strong>Analistas de datos haciendo análisis exploratorio</strong> → Plotly + Jupyter o Metabase</li><li><strong>Pantallas de monitorización de operaciones</strong> → Grafana (el estándar de facto)</li><li><strong>Equipos de negocio para autoanálisis</strong> → Metabase (código abierto) o Tableau (comercial)</li><li><strong>Necesidad de alta personalización</strong> → D3.js (curva de aprendizaje pronunciada, pero la mayor flexibilidad)</li></ul></div><hr><h2 id="_5-errores-comunes-estos-graficos-te-estan-enganando" tabindex="-1">5. Errores comunes: Estos gráficos te están engañando <a class="header-anchor" href="#_5-errores-comunes-estos-graficos-te-estan-enganando" aria-label="Permalink to “5. Errores comunes: Estos gráficos te están engañando”">​</a></h2><p>La visualización de datos es un arma de doble filo: bien usada revela la verdad, mal usada crea ilusiones. Estos son los errores de visualización más comunes que todo profesional de datos debería poder identificar.</p><h3 id="_5-1-ejes-truncados" tabindex="-1">5.1 Ejes truncados <a class="header-anchor" href="#_5-1-ejes-truncados" aria-label="Permalink to “5.1 Ejes truncados”">​</a></h3><p>Cambiar el punto de partida del eje Y de 0 a un número grande hace que las diferencias minúsculas parezcan cambios enormes.</p><table tabindex="0"><thead><tr><th>Escenario</th><th>Diferencia real</th><th>Impresión visual</th></tr></thead><tbody><tr><td>Eje Y desde 0</td><td>Producto A: 98 puntos, Producto B: 95 puntos</td><td>La diferencia es pequeña</td></tr><tr><td>Eje Y desde 90</td><td>Mismos datos</td><td>A parece varias veces mayor que B</td></tr></tbody></table><p><strong>¿Cuándo es aceptable truncar?</strong> Cuando el valor absoluto de los datos es grande pero el cambio es pequeño (como el precio de una acción de 100 a 105), truncar es razonable, pero debe indicarse claramente.</p><h3 id="_5-2-la-trampa-de-la-perspectiva-en-graficos-de-pastel-3d" tabindex="-1">5.2 La trampa de la perspectiva en gráficos de pastel 3D <a class="header-anchor" href="#_5-2-la-trampa-de-la-perspectiva-en-graficos-de-pastel-3d" aria-label="Permalink to “5.2 La trampa de la perspectiva en gráficos de pastel 3D”">​</a></h3><p>La perspectiva 3D hace que los sectores más cercanos al observador parezcan más grandes. Un sector del 25% puede parecer del 35% en una vista 3D.</p><p><strong>Solución</strong>: Nunca uses gráficos de pastel 3D. Usa gráficos de pastel normales o de anillo, o simplemente usa un gráfico de barras.</p><h3 id="_5-3-uso-excesivo-de-color" tabindex="-1">5.3 Uso excesivo de color <a class="header-anchor" href="#_5-3-uso-excesivo-de-color" aria-label="Permalink to “5.3 Uso excesivo de color”">​</a></h3><table tabindex="0"><thead><tr><th>Práctica incorrecta</th><th>Práctica correcta</th></tr></thead><tbody><tr><td>Usar rojo y verde para representar datos</td><td>Usar combinaciones seguras para daltónicos como azul-naranja</td></tr><tr><td>Cada categoría con un color diferente</td><td>Misma serie con variaciones de tono de un mismo color</td></tr><tr><td>Codificar datos continuos con color pero sin leyenda</td><td>Siempre proporcionar leyenda de color y etiquetas numéricas</td></tr><tr><td>Contraste insuficiente entre color de fondo y color de datos</td><td>Asegurar un contraste de nivel WCAG AA</td></tr></tbody></table><h3 id="_5-4-otros-errores-comunes" tabindex="-1">5.4 Otros errores comunes <a class="header-anchor" href="#_5-4-otros-errores-comunes" aria-label="Permalink to “5.4 Otros errores comunes”">​</a></h3><table tabindex="0"><thead><tr><th>Trampa</th><th>Problema</th><th>Solución</th></tr></thead><tbody><tr><td>Doble eje Y</td><td>Dos indicadores no relacionados comparten el eje X, sugiriendo una relación causal</td><td>Separar en dos gráficos o aclarar que no hay causalidad</td></tr><tr><td>Distorsión por área</td><td>Usar el radio del círculo en lugar del área para representar valores</td><td>Cuando el valor se duplica, el área debe duplicarse, no el radio</td></tr><tr><td>Eje temporal no uniforme</td><td>Enero, marzo y diciembre tienen el mismo espaciado</td><td>Ordenar según la proporción de tiempo real</td></tr><tr><td>Demasiadas categorías</td><td>Gráfico de pastel con 15 sectores</td><td>Más de 5 categorías: usar gráfico de barras o agrupar en &quot;Otros&quot;</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Código ético de la visualización</p><p>El propósito de la visualización es <strong>ayudar a comprender</strong>, no <strong>manipular la percepción</strong>. Cada vez que hagas un gráfico, pregúntate:</p><ul><li>Si yo fuera el lector, ¿este gráfico me llevaría a una conclusión errónea?</li><li>¿Estoy ocultando datos desfavorables?</li><li>¿Los ejes, las escalas y los colores representan los datos de manera justa?</li></ul></div><hr><h2 id="resumen" tabindex="-1">Resumen <a class="header-anchor" href="#resumen" aria-label="Permalink to “Resumen”">​</a></h2><p>La visualización de datos es la &quot;última milla&quot; en la transmisión del valor de los datos. Por muy bueno que sea un análisis, si no puede ser comprendido correctamente, es como si no existiera.</p><p>Repasemos los puntos clave de este capítulo:</p><ol><li><strong>Elegir el gráfico correcto</strong>: Seleccionar el tipo de gráfico según el propósito de los datos (comparación, tendencia, proporción, distribución, relación)</li><li><strong>Principios de diseño</strong>: Alto ratio tinta-datos, consistencia y legibilidad son los tres principios fundamentales</li><li><strong>Diseño de dashboards</strong>: Los cuatro patrones (panorámico, comparativo, de profundización y en tiempo real) cubren la mayoría de los escenarios</li><li><strong>Selección de herramientas</strong>: Desde ECharts hasta Grafana, elegir según la capacidad del equipo y la complejidad de los requisitos</li><li><strong>Evitar trampas</strong>: Los ejes truncados, los gráficos de pastel 3D y el uso excesivo de color son los métodos engañosos más comunes</li></ol><h2 id="lecturas-adicionales" tabindex="-1">Lecturas adicionales <a class="header-anchor" href="#lecturas-adicionales" aria-label="Permalink to “Lecturas adicionales”">​</a></h2><ul><li><a href="https://www.edwardtufte.com/tufte/books_vdqi" target="_blank" rel="noreferrer">The Visual Display of Quantitative Information</a> - El clásico de visualización de Edward Tufte</li><li><a href="https://echarts.apache.org/zh/index.html" target="_blank" rel="noreferrer">Documentación oficial de ECharts</a> - La biblioteca de gráficos en chino más popular</li><li><a href="https://d3js.org/" target="_blank" rel="noreferrer">D3.js</a> - Potente biblioteca de visualización de bajo nivel</li><li><a href="https://grafana.com/" target="_blank" rel="noreferrer">Grafana</a> - El estándar de facto para visualización de monitorización</li><li><a href="https://www.data-to-viz.com/" target="_blank" rel="noreferrer">From Data to Viz</a> - Árbol de decisión para selección de tipos de gráficos</li><li><a href="https://colorbrewer2.org/" target="_blank" rel="noreferrer">ColorBrewer</a> - Herramienta de esquemas de color seguros para daltónicos</li></ul>',35))])}const v=s(l,[["render",c]]);export{f as __pageData,v as default};
